-- Table: `attendance_tbl`
DROP TABLE IF EXISTS `attendance_tbl`;
CREATE TABLE `attendance_tbl` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `student_no` varchar(50) NOT NULL,
  `name` varchar(100) NOT NULL,
  `course` varchar(100) DEFAULT NULL,
  `section` varchar(100) DEFAULT NULL,
  `subject` varchar(100) DEFAULT NULL,
  `instructor` varchar(100) DEFAULT NULL,
  `time_in` varchar(50) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_section` (`user_id`,`section`),
  KEY `idx_section_date` (`section`,`date`),
  KEY `idx_student_date` (`student_no`,`date`),
  KEY `idx_date` (`date`),
  KEY `idx_user_date` (`user_id`,`date`)
) ENGINE=InnoDB AUTO_INCREMENT=6198 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: `group_details`
