-- Table: `instructor_section_tbl`
DROP TABLE IF EXISTS `instructor_section_tbl`;
CREATE TABLE `instructor_section_tbl` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `instructor_id` int(11) NOT NULL,
  `section` varchar(50) NOT NULL,
  `course` varchar(50) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `instructor_id` (`instructor_id`,`section`),
  UNIQUE KEY `unique_section_instructor` (`section`,`instructor_id`),
  UNIQUE KEY `unique_course_section_instructor` (`course`,`section`,`instructor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=185 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Data for `instructor_section_tbl` (1 rows)
INSERT INTO `instructor_section_tbl` (`id`, `instructor_id`, `section`, `course`) VALUES
('184', '1', '2A', 'BSIT');

-- Table: `lock_settings_tbl`
DROP TABLE IF EXISTS `lock_settings_tbl`;
CREATE TABLE `lock_settings_tbl` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(100) DEFAULT NULL,
  `setting_value` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `setting_key` (`setting_key`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Data for `lock_settings_tbl` (1 rows)
INSERT INTO `lock_settings_tbl` (`id`, `setting_key`, `setting_value`) VALUES
('1', 'page_locked', 'false');

-- Table: `student_photos`
DROP TABLE IF EXISTS `student_photos`;
CREATE TABLE `student_photos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `s_id` int(11) NOT NULL,
  `photo_path` varchar(255) NOT NULL,
  `uploaded_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `s_id` (`s_id`),
  CONSTRAINT `fk_student_photo` FOREIGN KEY (`s_id`) REFERENCES `students_tbl` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1681 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

