-- Table: `student_subjects_tbl`
DROP TABLE IF EXISTS `student_subjects_tbl`;
CREATE TABLE `student_subjects_tbl` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_no` varchar(20) NOT NULL,
  `subject_code` varchar(20) NOT NULL,
  `section` varchar(10) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_enrollment` (`student_no`,`subject_code`),
  KEY `idx_subject_code` (`subject_code`),
  KEY `idx_student_no` (`student_no`)
) ENGINE=InnoDB AUTO_INCREMENT=6757 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

