-- Table: `users`
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `avatar` varchar(255) DEFAULT NULL COMMENT 'Relative path ng profile picture, hal. uploads/avatars/user_1.jpg',
  `password` varchar(255) DEFAULT NULL,
  `face_descriptor` text DEFAULT NULL COMMENT 'Stores face recognition data as JSON array',
  `face_enabled` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Whether face recognition is enabled for this user',
  `last_login` timestamp NULL DEFAULT NULL COMMENT 'Last login timestamp',
  `role` enum('admin','instructor') DEFAULT 'instructor',
  `status` enum('active','disabled') DEFAULT 'active',
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_face_enabled` (`face_enabled`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

